extern "C" char* strcpy(char*, const char*);

class chunk_file {};

class chunk_flavor
{
private:
  char flavor[16];
public:
  enum { CHUNK_FLAVOR_SIZE=16 };
  chunk_flavor(const char* s="UNREG") { strcpy( flavor, s ); }
  bool operator==( const chunk_flavor& cf ) const;
  bool operator!=( const chunk_flavor& cf ) const;
};

class stringx
{
protected:
  char *chars;
  void *my_buf;
public:
  stringx();
  stringx(const stringx &cp);
  stringx(const char *str, int len = -1);
  ~stringx();
  stringx &operator=(const stringx &cp);
};

extern const chunk_flavor CHUNK_END;
void serial_in(chunk_file& io,chunk_flavor* d);
void serial_in(chunk_file& io, int* d);
void serial_in(chunk_file& io, float* d);
void serial_in(chunk_file& io, stringx* d);
void error(const char*, ...);

class lod_info
{
public:
  float ranges[4];
  stringx names[4];

  lod_info( void )
  {
    for( int i = 0; i < 3; i++ ) {
      ranges[i] = 0.0f;
    }
  }
};

void serial_in( chunk_file& fs, lod_info* lod )
{
  chunk_flavor cf;
  int level;
  float range;
  stringx name;

  for( serial_in( fs, &cf ); cf != CHUNK_END; serial_in( fs, &cf ) ) {

    if( cf == chunk_flavor( "level" ) ) {
      serial_in( fs, &level );
    } else if( cf == chunk_flavor( "range" ) ) {
      serial_in( fs, &range );
    } else if( cf == chunk_flavor( "name" ) ) {
      serial_in( fs, &name );
    } else {
      error( "unknown chunk parsing lod tag" );
    }

  }

  lod->ranges[level] = range;
  lod->names[level] = name;
}
